const txLink = (txid, text = txid) => `<a href="${EXPLORER}/tx/${esc(txid)}" target="_blank" rel="noopener">${esc(text)}</a>`;

// ---- banners: one line each at the top of the window, for what the person must know now
function banner(id, cls, text, actions = []) { let el = document.querySelector(`#banners [data-b="${id}"]`); if (!el) { el = document.createElement('div'); el.dataset.b = id; $('banners').appendChild(el); }
  el.className = 'banner ' + cls; el.setAttribute('role', cls === 'bad' ? 'alert' : 'status'); el.textContent = ''; const t = document.createElement('span'); t.textContent = text; el.appendChild(t);
  for (const [label, fn] of actions) { const b = document.createElement('button'); b.className = 'q'; b.textContent = label; b.onclick = fn; el.appendChild(b); } }
const unbanner = (id) => document.querySelector(`#banners [data-b="${id}"]`)?.remove();
function showFatal(text) { $('syncmsg').textContent = text; banner('fatal', 'bad', text, [['Reload', () => location.reload()]]); }

// ---- the libraries; a CDN outage is said in words, not as a dead page
let createTabNode, mib, secs, n, WL;
