async function begin() {
  let sole = true; if (navigator.locks) await new Promise((res) => navigator.locks.request('reef:node', { ifAvailable: true }, (lock) => { sole = !!lock; res(); return lock ? new Promise(() => {}) : undefined; }).catch(() => res()));
  if (!sole) { banner('twotabs', 'warn', 'Reef is already open in another tab of this browser. This one stays idle: two tabs would fight over the node\'s files and could spend the same coins twice. Close the other tab and reload here to use this one.', [['Reload', () => location.reload()]]); setSync('idle: Reef runs in another tab', null); $('sendgo').disabled = true; return; }
  if (LS.get('reef:started') || RETURNING) { LS.set('reef:started', String(Date.now())); return startNode(); }
  const est = await navigator.storage?.estimate?.().catch(() => null); const free = est ? est.quota - est.usage : null;
  $('wl-space').textContent = free == null ? 'The browser does not say how much space it allows.' : free < 1.2e9 ? `The browser allows ${mib(free)} more for this site, less than the 1.1 GB needed: free disk space first, or the fetch will stop part-way.` : `The browser allows ${mib(free)} for this site; 1.1 GB is needed.`;
  $('wl-start').onclick = async () => { $('welcome').close(); LS.set('reef:started', String(Date.now())); navigator.storage?.persist?.().catch(() => {}); if (OPT.notify && 'Notification' in window && Notification.permission === 'default') Notification.requestPermission().catch(() => {}); startNode(); };
  $('wl-later').onclick = () => { $('welcome').close(); setSync('not started: nothing is downloaded until you choose Start', null); banner('welcome', 'info', 'The node is not started. Nothing is downloaded until you start it.', [['Start the node…', () => $('welcome').showModal()]]); };
  $('welcome').showModal(); }
